// ASIM: imAuditEvent — native (AzureActivity → imAuditEvent Audit Event schema)
// Control: AIGS-CD001
// Data Contract: AzureActivity | OperationNameValue in raiPolicies write/delete
//   Confirmed ARM operations (Trinity verified, 2026-07-17):
//     microsoft.cognitiveservices/accounts/raipolicies/write
//     microsoft.cognitiveservices/accounts/raipolicies/delete
// Watchlist (required for any alert): AIGS_ContentFilterPolicies — Active baseline entries only
//   itemsSearchKey: ItemKey (watchlist search index column is named ItemKey)
//   Match keys: AccountName (AzureActivity → watchlist) + PolicyTarget == WL_PolicyName (PolicyName column)
//   Watchlist schema (Tank-owned JSON metadata): ItemKey (itemsSearchKey), PolicyName, AccountName, ResourceId,
//     HateSeverityThreshold, ViolenceSeverityThreshold, SelfHarmSeverityThreshold,
//     SexualSeverityThreshold, JailbreakEnabled, IndirectAttackEnabled, Status, BaselineVersion
// FAIL-CLOSED: inner join on AccountName + PolicyName filter — if watchlist has no Active entries,
//   zero results produced. Empty or template-only baseline = no alerts.
// WARNING: ARM write/delete does NOT confirm policy removal or filter weakening.
//   All results are drift candidates requiring validation of current policy state.
//   PB-AUTO-01 cannot restore policies — AzureActivity lacks the before-state policy body.
let RaiPolicyOps = dynamic([
    "microsoft.cognitiveservices/accounts/raipolicies/write",
    "microsoft.cognitiveservices/accounts/raipolicies/delete"
]);
// Load Active baseline entries only; empty result if watchlist absent or has no Active rows
// Fail-closed: inner join below yields zero results when BaselineResources is empty
let BaselineResources = materialize(
    _GetWatchlist("AIGS_ContentFilterPolicies")
    | where Status =~ "Active"
    | project
        WL_AccountName     = tolower(AccountName),
        WL_PolicyName      = tolower(PolicyName),   // PolicyName column (ItemKey is the itemsSearchKey index column)
        WL_HateSev         = HateSeverityThreshold,
        WL_ViolenceSev     = ViolenceSeverityThreshold,
        WL_JailbreakOn     = JailbreakEnabled,
        WL_IndirectOn      = IndirectAttackEnabled
);
AzureActivity
| where TimeGenerated >= ago(1h)
| where tolower(OperationNameValue) in (RaiPolicyOps)
| where ActivityStatusValue =~ "Success"
| extend
    // Extract CognitiveServices account name and raiPolicy name from ARM resource path
    // Path pattern: .../accounts/{accountName}/raiPolicies/{policyName}
    AccountName  = tostring(extract(@"/accounts/([^/]+)", 1, tolower(_ResourceId))),
    PolicyTarget = tostring(extract(@"/raipolicies/([^/]+)", 1, tolower(_ResourceId))),
    OperationType = iff(tolower(OperationNameValue) has "delete", "Delete", "Write")
// Inner join on AccountName: events on accounts with Active baseline entries only
// If BaselineResources is empty, inner join yields zero results (fail-closed)
| join kind=inner (BaselineResources) on $left.AccountName == $right.WL_AccountName
// Require the specific policy to be explicitly Active in the baseline (ItemKey match)
// Policies not listed as Active in AIGS_ContentFilterPolicies do not trigger alerts
| where PolicyTarget == WL_PolicyName
| extend
    DriftFlag = case(
        OperationType == "Delete",
            "HIGH — Delete on Active baseline policy; validate policy still present via REST API",
        OperationType == "Write",
            "MEDIUM — Write on Active baseline policy; validate policy values unchanged via REST API",
        "INFO — Review"
    ),
    DriftCandidateNote = strcat(
        "Drift candidate — investigation required. ",
        "This alert confirms a successful ARM ", OperationType, " on an Active baseline raiPolicy ",
        "(account: ", AccountName, ", policy: ", PolicyTarget, "). ",
        "It does NOT confirm removal or weakening of content filters. ",
        "PB-AUTO-01 cannot restore this policy — AzureActivity lacks before-state. ",
        "Verify current policy state via Azure Portal or REST API before escalating."
    )
| project
    TimeGenerated,
    OperationType,
    OperationNameValue,
    _ResourceId,
    AccountName,
    PolicyTarget,
    Caller,
    CallerIpAddress,
    SubscriptionId,
    ResourceGroup,
    ActivityStatusValue,
    WL_PolicyName,
    WL_HateSev,
    WL_ViolenceSev,
    WL_JailbreakOn,
    DriftFlag,
    DriftCandidateNote,
    CorrelationId

// ASIM: imAuditEvent — native (AzureActivity → imAuditEvent Audit Event schema)
// Control: AIGS-CD005
// Data Contract: AzureActivity | Microsoft.Insights/diagnosticSettings write/delete
//   Confirmed ARM operations (documented Azure REST API):
//     microsoft.insights/diagnosticsettings/write
//     microsoft.insights/diagnosticsettings/delete
//   Resource scope: _ResourceId contains "microsoft.cognitiveservices" (AI resources only)
// Baseline scope: AIGS_ContentFilterPolicies (Status=Active AccountName field)
//   Rationale: AccountName identifies the approved AI resource set; diagnostic-settings
//   changes on accounts NOT in this baseline are out-of-scope for this rule.
//   Note: AIGS_ContentFilterPolicies does not define expected diagnostic log categories
//   or workspace destinations. This rule scopes to the resource, not to specific settings values.
//   PB-AUTO-01 NOT referenced: AzureActivity lacks the before-state settings body; no
//   baseline-safe automatic restoration is possible from this alert.
// FAIL-CLOSED: inner join on AccountName — if watchlist has no Active entries, zero results.
let DiagOps = dynamic([
    "microsoft.insights/diagnosticsettings/write",
    "microsoft.insights/diagnosticsettings/delete"
]);
// Active AI resource scope from AIGS_ContentFilterPolicies
// Empty or no-Active entries → inner join yields zero results (fail-closed)
let ApprovedResources = materialize(
    _GetWatchlist("AIGS_ContentFilterPolicies")
    | where Status =~ "Active"
    | project WL_AccountName = tolower(AccountName)
    | distinct WL_AccountName
);
AzureActivity
| where TimeGenerated >= ago(1h)
| where tolower(OperationNameValue) in (DiagOps)
| where ActivityStatusValue =~ "Success"
// Pre-filter: scope to CognitiveServices resources before join (performance + precision)
// NOTE: Diagnostic settings operations are logged under the Microsoft.Insights provider
//       but the _ResourceId path still contains the parent CognitiveServices account.
| where tolower(_ResourceId) contains "microsoft.cognitiveservices"
| extend
    // Extract account name and diagnostic setting name from ARM resource path
    // Path: .../providers/Microsoft.CognitiveServices/accounts/{acct}/providers/microsoft.insights/diagnosticSettings/{settingName}
    AccountName   = tostring(extract(@"/accounts/([^/]+)", 1, tolower(_ResourceId))),
    SettingName   = tostring(extract(@"/diagnosticsettings/([^/]+)", 1, tolower(_ResourceId))),
    OperationType = iff(tolower(OperationNameValue) has "delete", "Delete", "Write")
// Inner join: only accounts with Active baseline entries trigger alerts (fail-closed)
| join kind=inner (ApprovedResources) on $left.AccountName == $right.WL_AccountName
| extend
    SeverityIndicator = case(
        OperationType == "Delete",
            "HIGH — Diagnostic setting deleted on Active baseline resource; audit-log forwarding may be interrupted",
        OperationType == "Write",
            "MEDIUM — Diagnostic setting written on Active baseline resource; validate required log categories and destinations are preserved",
        "INFO — Diagnostic setting operation on baseline resource; review required"
    ),
    RemediationNote = strcat(
        "Notify SOC via PB-NOTIFY-01 and investigate. ",
        "Confirm that diagnostic setting '", SettingName, "' on account '", AccountName, "' ",
        "retains all required log categories (Audit, RequestResponse, Trace) ",
        "and forwards to the approved Log Analytics workspace. ",
        "PB-AUTO-01 is not applicable: AzureActivity lacks the before-state settings body; ",
        "restoration requires manual baseline comparison and remediation."
    )
| project
    TimeGenerated,
    OperationType,
    OperationNameValue,
    _ResourceId,
    AccountName,
    SettingName,
    Caller,
    CallerIpAddress,
    SubscriptionId,
    ResourceGroup,
    ActivityStatusValue,
    SeverityIndicator,
    RemediationNote,
    CorrelationId

// ASIM: imAuditEvent — native (AzureActivity → imAuditEvent Audit Event schema)
// Control: AIGS-AM001 (reference hunt)
// Data Contract: AzureActivity | CognitiveServices deployments/write (Success only)
//   ARM operations targeted:
//     microsoft.cognitiveservices/accounts/deployments/write
//   ActivityStatusValue == "Success" — avoids noise from Start/Accepted transient states
// Watchlist (optional): AIGS_ApprovedModels — approved model names and versions
//   DeploymentName in watchlist = the approved deployment name; ModelId = model family name
//   Graceful degradation: if watchlist absent, all successful deployment events are surfaced
// CAVEAT: Model name is extracted from the ARM deployment resource path (deployment name
//   often but not always matches the model family name). Analysts should verify the actual
//   model name from the ARM resource if the deployment name is a custom alias.
// LOCATION CAVEAT: AzureActivity does not contain resource location.
//   Region validation requires Azure Resource Graph correlation outside Sentinel KQL.
//   Do not infer region from ResourceGroup — ResourceGroup is not a region proxy.
let LookbackPeriod = 14d;
let DeployOp = "microsoft.cognitiveservices/accounts/deployments/write";
// Load AIGS_ApprovedModels baseline; returns empty result if watchlist not deployed
// Watchlist schema (Tank-owned JSON metadata): ModelId (searchKey), DeploymentName, AccountName,
//   ResourceGroupName, SubscriptionId, ApprovedVersion, MaxCapacityTPM, Region, Status, BaselineVersion
// Note: Region column is in the watchlist schema for documentation; NOT used for filtering here
//   because AzureActivity does not contain resource location data.
let ApprovedModels = materialize(
    _GetWatchlist("AIGS_ApprovedModels")
    | where Status =~ "Active"
    | project
        AM_DeploymentName  = tolower(DeploymentName),
        AM_ModelId         = ModelId,
        AM_ApprovedVersion = ApprovedVersion,
        AM_MaxCapacityTPM  = MaxCapacityTPM,
        AM_AccountName     = tolower(AccountName)
);
let WatchlistDeployed = toscalar(ApprovedModels | summarize n = count() | project n > 0);
AzureActivity
| where TimeGenerated >= ago(LookbackPeriod)
| where tolower(OperationNameValue) == DeployOp
| where ActivityStatusValue =~ "Success"
| extend
    // Extract account name and deployment name from ARM resource path
    // Path: .../providers/Microsoft.CognitiveServices/accounts/{acct}/deployments/{deploymentName}
    AccountName    = tostring(extract(@"/accounts/([^/]+)", 1, tolower(_ResourceId))),
    DeploymentName = tostring(extract(@"/deployments/([^/]+)", 1, tolower(_ResourceId)))
// Left-outer join on deployment name; matches watchlist rows where deployment name is known
| join kind=leftouter (ApprovedModels) on $left.DeploymentName == $right.AM_DeploymentName
| extend
    InApprovedBaseline = isnotempty(AM_ModelId),
    ApprovalStatus = case(
        not(WatchlistDeployed),
            "INFO — Watchlist not deployed; event surfaced for baseline seeding. Baseline comparison unavailable.",
        not(isnotempty(AM_ModelId)),
            "FLAG — Deployment name not found in AIGS_ApprovedModels baseline; analyst validation required",
        "IN-BASELINE — Deployment name matches approved entry; verify model version. NOTE: location validation requires Azure Resource Graph."
    )
// Scope: flag unapproved when watchlist deployed; surface all when watchlist absent
| where not(InApprovedBaseline) or not(WatchlistDeployed)
| project
    TimeGenerated,
    ApprovalStatus,
    AccountName,
    DeploymentName,
    AM_ModelId,
    AM_ApprovedVersion,
    AM_MaxCapacityTPM,
    Caller,
    CallerIpAddress,
    SubscriptionId,
    ResourceGroup,
    OperationNameValue,
    ActivityStatusValue,
    _ResourceId,
    CorrelationId
| order by TimeGenerated desc
// --- Summary view (replace above project+order with this block for rollup) ---
// | summarize
//     TotalDeployments     = count(),
//     UniqueAccounts       = dcount(AccountName),
//     UniqueModels         = dcount(DeploymentName),
//     UniqueCallers        = dcount(Caller),
//     CallerList           = make_set(Caller, 10),
//     ModelsDeployed       = make_set(DeploymentName, 30),
//     FirstDeployment      = min(TimeGenerated),
//     LastDeployment       = max(TimeGenerated)
//     by ApprovalStatus, SubscriptionId, ResourceGroup
// | order by TotalDeployments desc

// ASIM: imAuditEvent — native (AzureActivity → imAuditEvent Audit Event schema)
// Control: AIGS-CD001 (reference hunt)
// Data Contract: AzureActivity | raiPolicies write/delete (all outcome statuses)
//   ARM operations targeted:
//     microsoft.cognitiveservices/accounts/raipolicies/write
//     microsoft.cognitiveservices/accounts/raipolicies/delete
// Lookback default: 14 days — adjust for deeper historical investigation
// Analyst tip: change final line to '| summarize ...' block (commented below) for per-account summary view
let LookbackPeriod = 14d;
let RaiPolicyOps = dynamic([
    "microsoft.cognitiveservices/accounts/raipolicies/write",
    "microsoft.cognitiveservices/accounts/raipolicies/delete"
]);
AzureActivity
| where TimeGenerated >= ago(LookbackPeriod)
| where tolower(OperationNameValue) in (RaiPolicyOps)
| extend
    AccountName   = tostring(extract(@"/accounts/([^/]+)", 1, tolower(_ResourceId))),
    PolicyTarget  = tostring(extract(@"/raipolicies/([^/]+)", 1, tolower(_ResourceId))),
    OperationType = iff(tolower(OperationNameValue) has "delete", "Delete", "Write")
| extend
    RiskSignal = case(
        OperationType == "Delete" and ActivityStatusValue =~ "Success",
            "HIGH — Successful delete; validate policy still present",
        OperationType == "Delete" and ActivityStatusValue =~ "Failure",
            "MEDIUM — Failed delete attempt; review caller intent",
        OperationType == "Write" and ActivityStatusValue =~ "Success",
            "MEDIUM — Successful write; validate policy values unchanged",
        "LOW — Review"
    )
| project
    TimeGenerated,
    RiskSignal,
    OperationType,
    OperationNameValue,
    ActivityStatusValue,
    AccountName,
    PolicyTarget,
    Caller,
    CallerIpAddress,
    SubscriptionId,
    ResourceGroup,
    _ResourceId,
    CorrelationId
| order by TimeGenerated desc
